#include <zephyr/drivers/comparator/fake_comp.h>
#include <zephyr/fff.h>
#include <zephyr/kernel.h>

#ifdef CONFIG_ZTEST
#include <zephyr/ztest.h>
#endif

#define DT_DRV_COMPAT zephyr_fake_comp

DEFINE_FAKE_VALUE_FUNC(int, comparator_fake_comp_get_output, const struct device *);
DEFINE_FAKE_VALUE_FUNC(int, comparator_fake_comp_set_trigger, const struct device *,
		       enum comparator_trigger);
DEFINE_FAKE_VALUE_FUNC(int, comparator_fake_comp_set_trigger_callback, const struct device *,
		       comparator_callback_t, void *);
DEFINE_FAKE_VALUE_FUNC(int, comparator_fake_comp_trigger_is_pending, const struct device *);

#ifdef CONFIG_ZTEST
static void comparator_fake_comp_reset_rule_before(const struct ztest_unit_test *test,
						   void *fixture)
{
	ARG_UNUSED(test);
	ARG_UNUSED(fixture);

	RESET_FAKE(comparator_fake_comp_get_output);
	RESET_FAKE(comparator_fake_comp_set_trigger);
	RESET_FAKE(comparator_fake_comp_set_trigger_callback);
	RESET_FAKE(comparator_fake_comp_trigger_is_pending);
}

ZTEST_RULE(comparator_fake_comp_reset_rule, comparator_fake_comp_reset_rule_before, NULL);
#endif

static DEVICE_API(comparator, comparator_fake_comp_api) = {
	.get_output = comparator_fake_comp_get_output,
	.set_trigger = comparator_fake_comp_set_trigger,
	.set_trigger_callback = comparator_fake_comp_set_trigger_callback,
	.trigger_is_pending = comparator_fake_comp_trigger_is_pending,
};

#define COMPARATOR_FAKE_COMP_DEFINE(inst)						\
	DEVICE_DT_INST_DEFINE(inst,							\
			      NULL,							\
			      NULL,							\
			      NULL,							\
			      NULL,							\
			      POST_KERNEL,						\
			      CONFIG_COMPARATOR_INIT_PRIORITY,				\
			      &comparator_fake_comp_api);

DT_INST_FOREACH_STATUS_OKAY(COMPARATOR_FAKE_COMP_DEFINE)
